// [WSCoop] On the server every SetTimeOfDay sends a reliable multicast (RPC_ExplicitServerUpdateEvent)
// to all clients. Doing it every tick overflows the reliable buffer of a client that is still loading
// and gets it kicked (RPCReliableBufferOverflow). Clients keep updating locally every frame; the
// server only re-syncs a few times per second.
private float WSServerTimeSyncAccumulator = 0;

if (System::IsServer() && Gameplay::GetNumPlayerControllers() > 0)
{
    WSServerTimeSyncAccumulator += DeltaSeconds;
    if (WSServerTimeSyncAccumulator < 0.5)
        return;
    WSServerTimeSyncAccumulator = 0;
}
